{"cards": [{"node_code": "N_766fe3a558461cd0", "definition": "研究材料在机械载荷作用下的响应特性，涵盖静态强度、动态疲劳、蠕变及硬度等力学性能的测试方法、标准与数据分析。", "boundary": "聚焦于材料在力、应力或应变激励下的物理响应。包括拉伸、压缩、弯曲、冲击、硬度、疲劳及高温蠕变等试验。侧重于量化材料的力学参数（如屈服强度、断裂韧性），不涉及材料微观组织成像或环境介质导致的化学损伤机理。", "includes": ["静态力学性能（拉伸、压缩、硬度）测试方法与标准", "动态力学性能（冲击、疲劳、断裂韧性）测试技术", "高温或特殊工况下的蠕变及松弛性能试验"], "excludes": ["材料微观组织、成分及晶体结构的静态表征（归成分、组织与结构表征）", "基于试验数据的失效模式识别与根因分析（归失效分析与材料完整性）"], "sibling_distinctions": [{"other_code": "N_4db680f5078c7d64", "rule": "本节点关注机械载荷下的力学响应；热物理节点关注温度场、热传导及电/磁/声等功能特性。"}, {"other_code": "N_529909ab561e32bb", "rule": "本节点关注纯力学或力-热耦合下的力学参数；环境节点关注化学介质、辐射等环境因素导致的性能衰减。"}], "cross_boundary_rule": "若试验主要目的是测定材料在特定载荷下的力学参数，归本节点；若涉及环境介质对力学性能的耦合影响，需根据主导因素判断，纯力学主导归本节点，环境损伤主导归环境节点。"}, {"node_code": "N_4db680f5078c7d64", "definition": "研究材料在热、电、磁、声等非力学场作用下的物理特性及功能性能的测试方法、标准与评估技术。", "boundary": "聚焦于材料的热物理性质（导热、热膨胀、比热）及功能特性（导电、导磁、声学、光学等）的量化测定。包括高温热稳定性、热震性能及功能材料在特定场下的响应测试。不涉及机械载荷下的力学行为或环境介质导致的化学腐蚀。", "includes": ["热物理性能（导热系数、热膨胀、热容）测试方法", "电、磁、声、光等功能性能测试技术与标准", "高温热稳定性及热震性能评估"], "excludes": ["材料微观组织、成分及晶体结构的静态表征（归成分、组织与结构表征）", "基于试验数据的失效模式识别与根因分析（归失效分析与材料完整性）"], "sibling_distinctions": [{"other_code": "N_766fe3a558461cd0", "rule": "本节点关注热、电、磁等功能特性；力学节点关注机械载荷下的强度、硬度等力学参数。"}, {"other_code": "N_529909ab561e32bb", "rule": "本节点关注材料固有功能特性或热物理参数；环境节点关注环境因素（如腐蚀、老化）导致的性能随时间变化。"}], "cross_boundary_rule": "若试验目的是测定材料在特定场（热、电、磁）下的固有物理参数，归本节点；若涉及环境介质对功能特性的长期影响，归环境节点。"}, {"node_code": "N_529909ab561e32bb", "definition": "研究材料在腐蚀、氧化、辐射、老化等环境因素作用下的性能衰减规律、加速试验方法及寿命评估技术。", "boundary": "聚焦于环境介质（化学、电化学、物理辐射等）与材料相互作用导致的性能变化。包括腐蚀速率测定、氧化增重、老化加速试验及环境应力开裂等。侧重于环境损伤机理的验证及材料在特定环境下的耐久性评估，不涉及纯力学或纯热物理参数的静态测定。", "includes": ["腐蚀、氧化、电化学性能测试与加速老化试验", "环境应力开裂、氢脆等环境耦合损伤试验", "材料在特定环境下的寿命预测与耐久性评估"], "excludes": ["材料微观组织、成分及晶体结构的静态表征（归成分、组织与结构表征）", "基于试验数据的失效模式识别与根因分析（归失效分析与材料完整性）"], "sibling_distinctions": [{"other_code": "N_766fe3a558461cd0", "rule": "本节点关注环境因素导致的性能衰减；力学节点关注纯力学载荷下的响应。"}, {"other_code": "N_4db680f5078c7d64", "rule": "本节点关注环境作用下的动态变化；热物理节点关注材料固有的热/电/磁参数。